.hero-mock { padding: 18px; }
.mock-top { display:flex; align-items:center; justify-content:space-between; margin-bottom:14px; }
.dot { width: 9px; height: 9px; border-radius: 50%; background: oklch(0.82 0.02 275); }
.wave { height: 70px; border-radius: 12px; background: linear-gradient(90deg, oklch(0.92 0.06 280), oklch(0.88 0.09 265)); }
