  width: 38px; height: 38px; border-radius: 12px;
  background: oklch(0.95 0.04 280);
  color: oklch(0.48 0.2 280);
  display:flex; align-items:center; justify-content:center; font-weight: 800;
}
.kpis { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.kpi { padding: 22px; text-align: center; }
.kpi .num { font-size: 2rem; font-weight: 800; }
.kpi p { margin: 2px 0 0; color: var(--muted); }
.logos { display:grid; grid-template-columns: repeat(6,1fr); gap: 12px; }
.logo { padding: 14px; text-align: center; font-weight: 700; color: var(--muted); }
.footer { padding: 42px 0 70px; color: var(--muted); }
.pricing-header { padding: 54px 0 24px; }
.toggle-wrap { display:flex; align-items:center; gap:12px; }
