.billing-toggle button { border:0; background: transparent; padding:8px 14px; border-radius:999px; font-weight:700; cursor:pointer; color: var(--muted); }
.billing-toggle .active { background: var(--surface); color: var(--text); box-shadow: var(--shadow); }
.pricing-grid { display:grid; grid-template-columns: repeat(4, 1fr); gap: 16px; margin: 22px 0 14px; }
.plan { padding: 22px; }
.plan .price { font-size: 2rem; font-weight: 800; margin: 4px 0; }
.plan ul { padding-left: 18px; color: var(--muted); }
.plan li { margin: 6px 0; }
.small-link { color: oklch(0.47 0.17 280); font-weight:700; font-size:.92rem; cursor:pointer; }
.hidden { display:none !important; }
.slider-row { margin: 20px 0; }
.slider { width: 100%; accent-color: oklch(0.58 0.22 285); }
.table-wrap { overflow:auto; border:1px solid var(--border); border-radius: var(--radius); background: var(--surface); }
table { width:100%; border-collapse: collapse; min-width: 860px; }
th, td { padding: 13px 14px; border-bottom: 1px solid var(--border); text-align:left; }
th { background: oklch(0.975 0.01 275); }
.faq-item { border-bottom:1px solid var(--border); }
.faq-btn { width:100%; text-align:left; border:0; background: transparent; padding: 16px 0; font-weight:700; cursor:pointer; display:flex; justify-content:space-between; }
.faq-answer { color: var(--muted); padding: 0 0 14px; }
.auth-wrap { min-height: calc(100vh - 72px); display:grid; place-items:center; padding: 34px 0; }
.auth-card { width:min(450px, 94vw); padding: 24px; }
.auth-card h1 { margin:0 0 8px; }
.form-row { display:flex; flex-direction:column; gap:8px; margin: 12px 0; }
input[type="email"] { padding: 12px 13px; border-radius: 12px; border:1px solid var(--border); font: inherit; }
.social-grid { display:grid; grid-template-columns:1fr 1fr; gap:10px; margin: 12px 0 8px; }
.social-grid .btn { width:100%; }
.signup-layout { display:grid; grid-template-columns: 1.1fr .9fr; gap: 20px; align-items: stretch; }
.testimonial { padding: 26px; background: linear-gradient(155deg, oklch(0.97 0.03 280), oklch(0.92 0.05 260)); }
.cookie-banner {
  position: fixed; left: 24px; bottom: 24px; width: min(520px, calc(100vw - 40px)); z-index: 50;
  padding: 16px; display:none;
}
.cookie-actions { display:flex; gap:10px; flex-wrap: wrap; margin-top: 10px; }
.modal-overlay {
  position: fixed; inset:0; background: rgba(16,10,31,.44); display:none; align-items:center; justify-content:center; z-index: 60;
}
.modal { width:min(560px, 94vw); padding: 22px; }
.pref-row { display:flex; justify-content:space-between; align-items:center; padding: 10px 0; border-bottom:1px solid var(--border); }
.switch { position:relative; width:46px; height:28px; }
.switch input { opacity:0; width:0; height:0; }
.knob { position:absolute; inset:0; background: oklch(0.86 0.02 275); border-radius:999px; transition:.2s; }
